package com.hssa.config; import io.swagger.v3.oas.models.OpenAPI; import io.swagger.v3.oas.models.info.Contact; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.info.License; import io.swagger.v3.oas.models.servers.Server; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import java.util.List; @Configuration public class OpenApiConfig { @Value("${spring.application.name}") private String applicationName; @Value("${swagger.server.url:http://localhost:8080}") private String serverUrl; @Bean public OpenAPI customOpenAPI() { return new OpenAPI().info(new Info().title(applicationName + " API").description("API Documentation for " + applicationName).version("v1.0.0").contact(new Contact().name("HSSA Support").email("support@hssa.com")).license(new License().name("Apache 2.0").url("http://springdoc.org"))).servers(List.of(new Server().url(serverUrl).description("Default Server URL"))); } }
